case 'tabla': return {
  t: 'tabla',
  orden: true,          // el vendedor puede ordenar tocando el título de la columna
  buscar: false,        // barra de búsqueda arriba de la tabla (para tablas largas)
  cols: [{ h: 'Concepto', num: false }, { h: 'Cantidad', num: true }],
  filas: [{ celdas: ['', ''], destaque: '' }, { celdas: ['', ''], destaque: '' }],
};

function tablaHTML(bk, ed) {
  const cols = bk.cols || [], filas = bk.filas || [];
  const ord = !!bk.orden, busc = !!bk.buscar;
  const th = cols.map((c, ci) => {
    const cls = [c.num ? 'num' : '', ord ? 'ord' : ''].filter(Boolean).join(' ');
    const txt = zona(ed, c.h, `data-prop="colh" data-c="${ci}"`, 'Columna');
    // el caret ▲▼↕ lo pone el CSS segun aria-sort: asi el HTML guardado no tiene estado
    const cap = ord ? '<span class="th-c" aria-hidden="true"></span>' : '';
    // publicado: <button> real (target de 44px, accesible por teclado).
    // canvas del editor: <span>, porque un contenteditable adentro de un <button> no se puede editar.
    const inner = !ord ? txt
      : (ed ? `<span class="th-b">${txt}${cap}</span>`
            : `<button type="button" class="th-b">${txt}${cap}</button>`);
    return `<th${cls ? ` class="${cls}"` : ''}${ord ? ' aria-sort="none"' : ''}>${inner}</th>`;
  }).join('');
  const tr = filas.map((f, ri) => {
    const celdas = f.celdas || [];
    const tds = cols.map((c, ci) =>
      `<td${c.num ? ' class="num"' : ''}>${zona(ed, celdas[ci], `data-prop="celda" data-r="${ri}" data-c="${ci}"`, '—')}</td>`).join('');
    return `<tr${f.destaque ? ` class="fx-${f.destaque}"` : ''}>${tds}</tr>`;
  }).join('');
  const tabla = `<div class="m-tabla"><table><thead><tr>${th}</tr></thead><tbody>${tr}</tbody></table></div>`;
  if (!ord && !busc) return tabla;          // sin ajustes: exactamente el mismo HTML de siempre
  // el envoltorio es OBLIGATORIO para el buscador: .m-tabla tiene overflow-x:auto y la
  // barra no puede quedar adentro (se iria de viaje con el scroll horizontal).
  const bar = busc ? `<div class="tb-bar">`
    + `<input type="search" class="tb-q" placeholder="Buscar en la tabla…" aria-label="Buscar en la tabla" autocomplete="off" enterkeyhint="search"${ed ? ' disabled title="Se activa cuando lo ve el vendedor"' : ''}>`
    + `<span class="tb-n" hidden></span>`
    + `<button type="button" class="tb-x" hidden>Limpiar</button>`
    + `</div>` : '';
  const tip = ord ? `<p class="tb-tip"><span aria-hidden="true">↕</span> Tocá un título para ordenar</p>` : '';
  const none = busc ? `<div class="tb-none" hidden>No hay filas que coincidan con la búsqueda.</div>` : '';
  return `<div class="m-tablaw">${bar}${tip}${tabla}${none}</div>`;
}

