  background:var(--surface); border:1px solid var(--border); border-radius:12px; -webkit-appearance:none; appearance:none; }
.manual .tb-q:focus{ outline:none; border-color:var(--ink); box-shadow:0 0 0 3px rgba(0,0,0,.07); }
