.manual .tb-x{ flex:0 0 auto; min-width:44px; height:44px; padding:0 14px; font:inherit; font-size:13px; font-weight:700;
  color:var(--ink2); background:var(--bg2); border:1px solid var(--border); border-radius:12px; cursor:pointer; }
