/* el <button> ocupa TODA la celda del encabezado: target real de 44px en el celular */
.manual .m-tabla th.ord{ padding:0; }
.manual .m-tabla th.ord .th-b{ display:flex; align-items:center; gap:7px; width:100%; min-height:44px; padding:0 14px;
  font:inherit; font-size:10.5px; font-weight:700; letter-spacing:1.1px; text-transform:uppercase; text-align:left;
  color:rgba(255,255,255,.72); background:none; border:0; cursor:pointer; -webkit-tap-highlight-color:transparent; }
.manual .m-tabla th.ord.num .th-b{ justify-content:flex-end; }
.manual .m-tabla th.ord .th-b:active{ background:rgba(255,255,255,.12); }
.manual .m-tabla th.ord .th-b:focus-visible{ outline:2px solid #fff; outline-offset:-3px; }
.manual .m-tabla th.ord .th-c{ flex:0 0 auto; font-size:11px; line-height:1; opacity:.45; }
.manual .m-tabla th.ord .th-c::before{ content:'↕'; }
.manual .m-tabla th.ord[aria-sort="descending"] .th-b,
.manual .m-tabla th.ord[aria-sort="ascending"]  .th-b{ color:#fff; }
