.manual .m-tabla th.ord[aria-sort="ascending"]  .th-c{ opacity:1; }
.manual .m-tabla th.ord[aria-sort="descending"] .th-c::before{ content:'▼'; }
.manual .m-tabla th.ord[aria-sort="ascending"]  .th-c::before{ content:'▲'; }
/* cebreado por clase: al filtrar, :nth-child sigue contando las filas ocultas */
.manual .m-tabla tbody tr[hidden]{ display:none; }
.manual .m-tabla tbody tr.z0{ background:var(--surface); }
.manual .m-tabla tbody tr.z1{ background:var(--bg2); }

/* ===================================================================
   TABLAS: ordenar tocando el titulo + buscador.
   El HTML lo emite el panel UNA sola vez (modulos.js). Aca vive solo la
   interaccion, colgada de document por delegacion porque #secBody se
   reescribe entero en cada navegacion (renderContent / verDoc / deckHTML).
   Si la tabla no tiene los ganchos del panel (th.ord / .m-tablaw) no pasa NADA.
   =================================================================== */
(function(){
  function tbTxt(el){ return el ? (el.textContent||'').replace(/\s+/g,' ').trim() : ''; }
  function tbNorm(s){                                  /* minusculas y sin acentos */
    s = String(s==null?'':s).toLowerCase();
    try{ s = s.normalize('NFD').replace(/[̀-ͯ]/g,''); }catch(e){}
    return s;
  }
  /* Formato argentino: punto = miles, coma = decimales.
       "1.116"->1116   "2.369"->2369   "4,5%"->4.5   "12,5% ★"->12.5
       "$ 1.234,50"->1234.5   "(1.234)"->-1234   "12.5"->12.5   "0"->0
     laxo=true  -> la columna esta declarada "Son numeros" en el panel (th.num):
                   se ignora cualquier texto sobrante (%, $, ★, etc).
     laxo=false -> si sobran letras NO es un numero (asi "Belgrano · CABA" o
                   "TOTAL MES" no se cuelan como numericos en el sniffing). */
  function tbNum(txt, laxo){
    var t = String(txt==null?'':txt).replace(/ /g,' ').trim();
    if(!t) return null;
    var m = t.match(/-?\d[\d.,\s]*\d|-?\d/);           /* nucleo numerico */
    if(!m) return null;
    if(!laxo && /[A-Za-zÀ-ÿ]{2,}/.test(t.replace(m[0],''))) return null;
    var core = m[0].replace(/\s/g,'');
    var neg = core.charAt(0)==='-' || /^\(.*\)$/.test(t);   /* (1.234) = negativo contable */
    core = core.replace(/-/g,'');
    var p = core.lastIndexOf('.'), c = core.lastIndexOf(',');
    if(p>=0 && c>=0)  core = (c>p) ? core.replace(/\./g,'').replace(',','.')  /* 1.234,50 */
                                   : core.replace(/,/g,'');                   /* 1,234.50 */
    else if(c>=0)     core = /^\d{1,3}(,\d{3})+$/.test(core) ? core.replace(/,/g,'') : core.replace(',','.');
    else if(p>=0 && /^\d{1,3}(\.\d{3})+$/.test(core)) core = core.replace(/\./g,''); /* 1.116 = mil ciento dieciseis */
    var n = parseFloat(core);
    return isFinite(n) ? (neg ? -n : n) : null;
  }
  function tbFecha(txt){                               /* "3/7/2026" -> 20260703 */
    var m = String(txt==null?'':txt).trim().match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
    if(!m) return null;
    var d=+m[1], me=+m[2], a=+m[3];
    if(d<1 || d>31 || me<1 || me>12) return null;
    if(a<100) a += (a<70 ? 2000 : 1900);
    return a*10000 + me*100 + d;
  }
  /* tipo de la columna: lo que dijo el dueño manda; si no, se olfatea el contenido */
  function tbTipo(filas, i, esNum){
    if(esNum) return 'n';
    var hay=0, nn=0, nf=0, t;
    for(var k=0;k<filas.length;k++){
      t = tbTxt(filas[k].cells[i]); if(!t) continue;
      hay++;
      if(tbFecha(t)!==null) nf++;
      else if(tbNum(t,false)!==null) nn++;
    }
    if(!hay) return 't';
    if(nf/hay >= .6) return 'f';
    if(nn/hay >= .6) return 'n';
    return 't';
  }
  function tbClave(tr, i, tipo){
    var t = tbTxt(tr.cells[i]);                        /* textContent: ignora <b>, <a>, ★ */
    if(!t) return null;                                /* vacia -> siempre al final */
    if(tipo==='f'){ var f = tbFecha(t); return f===null ? tbNum(t,true) : f; }
    if(tipo==='n') return tbNum(t,true);
    return t;
  }
  /* re-pinta el cebreado (nth-child cuenta las filas ocultas) + contador + vacio */
  function tbPintar(tabla){
    var n=0, vis=0, tot=0;
    Array.prototype.forEach.call(tabla.tBodies[0].rows, function(tr){
      if(!tr.classList.contains('fx-total')){ tot++; if(!tr.hidden) vis++; }
      if(tr.hidden){ tr.classList.remove('z0','z1'); return; }
      tr.classList.toggle('z0', n%2===0);
      tr.classList.toggle('z1', n%2!==0);
      n++;
    });
    var w = tabla.closest('.m-tablaw'); if(!w) return;
    var q = w.querySelector('.tb-q'), filtrando = !!(q && q.value.trim());
    var cont = w.querySelector('.tb-n'), x = w.querySelector('.tb-x'),
        none = w.querySelector('.tb-none'), caja = w.querySelector('.m-tabla');
    if(cont){ cont.textContent = filtrando ? (vis+' de '+tot) : ''; cont.hidden = !filtrando; }
    if(x)    x.hidden    = !filtrando;
    if(none) none.hidden = !(filtrando && !vis);
    if(caja) caja.hidden = filtrando && !vis;          /* sin resultados: ni el encabezado solo */
  }
  /* dir: -1 mayor->menor | 1 menor->mayor | 0 orden original */
  function tbOrdenar(tabla, i, dir){
    var tb = tabla.tBodies[0], th = tabla.tHead.rows[0].cells[i];
    var filas=[], total=[];
    Array.prototype.forEach.call(tb.rows, function(tr){
      (tr.classList.contains('fx-total') ? total : filas).push(tr);
    });
    if(!tabla._tb0) tabla._tb0 = filas.concat(total);  /* orden original: se guarda 1 sola vez */
    var lista;
    if(!dir) lista = tabla._tb0.slice();
    else {
      var tipo = tbTipo(filas, i, th.classList.contains('num'));
      var con=[], sin=[];
      filas.forEach(function(tr){
        var k = tbClave(tr, i, tipo);
        (k===null ? sin : con).push({ tr:tr, k:k });
      });
      con.sort(function(a,b){                          /* sort estable: los empates */
        var r = (tipo==='t')                           /* mantienen el orden original */
          ? String(a.k).localeCompare(String(b.k), 'es', { numeric:true, sensitivity:'base' })
          : (a.k - b.k);
        return dir<0 ? -r : r;
      });
      lista = con.map(function(o){ return o.tr; })
        .concat(sin.map(function(o){ return o.tr; }))  /* vacias: siempre al final */
        .concat(total);                                /* fila de total: siempre abajo */
    }
    var frag = document.createDocumentFragment();
    lista.forEach(function(tr){ frag.appendChild(tr); });
    tb.appendChild(frag);
    Array.prototype.forEach.call(tabla.tHead.rows[0].cells, function(c){
      if(c.classList.contains('ord')) c.setAttribute('aria-sort','none');
    });
    if(dir) th.setAttribute('aria-sort', dir<0 ? 'descending' : 'ascending');
    tbPintar(tabla);
  }
  function tbFiltrar(w){
    var tabla = w.querySelector('.m-tabla table');
    if(!tabla || !tabla.tBodies[0]) return;
    var q = w.querySelector('.tb-q');
    var partes = q ? tbNorm(q.value).split(/\s+/).filter(Boolean) : [];
    Array.prototype.forEach.call(tabla.tBodies[0].rows, function(tr){
      if(!partes.length){ tr.hidden = false; return; }
      if(tr.classList.contains('fx-total')){ tr.hidden = true; return; } /* el total ya no aplica */
      var txt = tbNorm(tr.textContent).replace(/\s+/g,' ');
      tr.hidden = !partes.every(function(p){ return txt.indexOf(p) >= 0; });
    });
    tbPintar(tabla);
  }
  document.addEventListener('click', function(e){
    if(!e.target.closest) return;
    var b = e.target.closest('.m-tabla th.ord .th-b');
    if(b && b.tagName === 'BUTTON'){
      var th = b.closest('th'), tabla = th.closest('table');
      if(!tabla || !tabla.tHead || !tabla.tBodies[0]) return;
      var est = th.getAttribute('aria-sort');
      /* 1er toque: el mas alto arriba -> 2do: el mas bajo -> 3ro: orden original */
      tbOrdenar(tabla, th.cellIndex, est==='descending' ? 1 : (est==='ascending' ? 0 : -1));
      return;
    }
    var x = e.target.closest('.m-tablaw .tb-x');
    if(x){
      var w = x.closest('.m-tablaw'), q = w.querySelector('.tb-q');
      if(q){ q.value=''; q.focus(); }
      tbFiltrar(w);
    }
  });
  document.addEventListener('input', function(e){
    if(!e.target.closest) return;
    var q = e.target.closest('.m-tablaw .tb-q');
    if(q) tbFiltrar(q.closest('.m-tablaw'));
  });
})();

