function insSelect(obj, prop, opts, fn) {
  const s = document.createElement('select'); s.className = 'insp-sel';
  s.innerHTML = opts.map(([v, n]) => `<option value="${esc(v)}">${esc(n)}</option>`).join('');
  s.value = String(obj[prop] == null ? '' : obj[prop]);
  s.onchange = () => { obj[prop] = s.value; if (fn) fn(s.value); renderCanvas(); renderInspector(); };
  return s;
}

/* --- tipo de dato de una columna de tabla ---------------------------------
   Antes el unico "tipo" era col.num (solo alineacion). Ahora hay col.tipo, y las
   columnas viejas (sin col.tipo) se derivan de col.num: nada que migrar. */
function colTipo(c) { return (c && c.tipo) || (c && c.num ? 'num' : 'texto'); }

/* "12/03/2026" | "12-3-26" | "2026-03-12" -> 20260312 (numero ordenable). 0 = no es fecha */
function fechaNum(v) {
  const t = txtOf(v).trim();
  let m = t.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
  if (m) { let a = +m[3]; if (a < 100) a += 2000; return a * 10000 + (+m[2]) * 100 + (+m[1]); }
  m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return (+m[1]) * 10000 + (+m[2]) * 100 + (+m[3]);
  return 0;
}

/* clave de orden de una celda, ya normalizada, para emitir como data-v.
   '' = la celda no aporta valor (vacia, o texto): esas se ordenan por su texto
   visible del lado de la intranet, y las vacias van SIEMPRE ultimas. */
function claveCelda(valor, tipo) {
  const t = txtOf(valor);
  if (!t) return '';
  if (tipo === 'fecha') { const f = fechaNum(valor); return f ? String(f) : ''; }
  if (tipo === 'num' || tipo === 'plata') return /\d/.test(t) ? String(numDe(valor)) : '';
  return '';
}

case 'tabla': return {
  t: 'tabla',
  cols: [{ h: 'Concepto', num: false, tipo: 'texto', filtrar: false },
         { h: 'Cantidad', num: true,  tipo: 'num',   filtrar: false }],
  filas: [{ celdas: ['', ''], destaque: '' }, { celdas: ['', ''], destaque: '' }],
  /* barra de ordenar/filtrar: apagada hasta que el dueno la prenda */
  ctrl: { on: false, buscar: true, ordenCol: '', ordenDir: 'desc' },
};

function tablaHTML(bk, ed) {
  const cols = bk.cols || [], filas = bk.filas || [], ctrl = bk.ctrl || {};
  const on = !!ctrl.on && cols.length > 0;      // <- barra de ordenar/filtrar activada

  const th = cols.map((c, ci) =>
    `<th${c.num ? ' class="num"' : ''}${on ? ` data-c="${ci}" data-tipo="${colTipo(c)}"` : ''}>` +
    `${zona(ed, c.h, `data-prop="colh" data-c="${ci}"`, 'Columna')}</th>`).join('');

  const tr = filas.map((f, ri) => {
    const celdas = f.celdas || [];
    const tds = cols.map((c, ci) => {
      const k = on ? claveCelda(celdas[ci], colTipo(c)) : '';
      return `<td${c.num ? ' class="num"' : ''}${k !== '' ? ` data-v="${esc(k)}"` : ''}>` +
             `${zona(ed, celdas[ci], `data-prop="celda" data-r="${ri}" data-c="${ci}"`, '—')}</td>`;
    }).join('');
    const fija = (on && f.destaque === 'total') ? ' data-fija="1"' : '';
    return `<tr${f.destaque ? ` class="fx-${f.destaque}"` : ''}${fija}>${tds}</tr>`;
  }).join('');

  const tabla = `<table><thead><tr>${th}</tr></thead><tbody>${tr}</tbody></table>`;
  if (!on) return `<div class="m-tabla">${tabla}</div>`;   // <- IDENTICO a lo publicado hasta hoy

  let oc = String(ctrl.ordenCol == null ? '' : ctrl.ordenCol);
  if (oc !== '' && !(+oc >= 0 && +oc < cols.length)) oc = '';   // borro una columna: se descarta solo
  const dir = ctrl.ordenDir === 'asc' ? 'asc' : 'desc';
  return `<div class="m-tabla t-int" data-t-orden="${oc}" data-t-dir="${dir}">`
       + tablaBarraHTML(bk, ed, oc)
       + `<div class="t-scroll">${tabla}</div></div>`;
}

/* Barra de controles. Sale COMPLETA y QUIETA desde el panel (incluidos los valores
   unicos de cada filtro): la intranet no genera markup, solo engancha comportamiento. */
function tablaBarraHTML(bk, ed, oc) {
  const cols = bk.cols || [], ctrl = bk.ctrl || {};
  const filas = (bk.filas || []).filter(f => f.destaque !== 'total');   // el total no es un dato
  const nom = (c, i) => txtOf(c.h) || ('Columna ' + (i + 1));

  const ordenOpts = ['<option value="">Como está cargada</option>'].concat(
    cols.map((c, i) => `<option value="${i}"${oc === String(i) ? ' selected' : ''}>${esc(nom(c, i))}</option>`)).join('');

  const filtros = cols.map((c, i) => {
    if (!c.filtrar) return '';
    const vistos = [], vals = [];
    filas.forEach(f => {
      const t = txtOf((f.celdas || [])[i]); if (!t) return;
      const k = t.toLowerCase();
      if (vistos.indexOf(k) < 0) { vistos.push(k); vals.push(t); }
    });
    if (vals.length < 2) return '';        // un solo valor distinto: el filtro no sirve para nada
    vals.sort((a, b) => a.localeCompare(b, 'es', { sensitivity: 'base', numeric: true }));
    return `<label class="t-f"><span class="t-lb">${esc(nom(c, i))}</span>`
         + `<select class="t-sel" data-t="filtro" data-c="${i}"><option value="">Todas</option>`
         + vals.map(v => `<option value="${esc(v)}">${esc(v)}</option>`).join('')
         + `</select></label>`;
  }).join('');

  const asc = ctrl.ordenDir === 'asc';
  const texto = oc === '' || colTipo(cols[+oc]) === 'texto';
  const dirTx = texto ? (asc ? 'A → Z' : 'Z → A') : (asc ? 'Menor a mayor' : 'Mayor a menor');
  const n = filas.length;

  return `<div class="t-ctrl"${ed ? ' data-preview="1"' : ''}>`
    + (ctrl.buscar === false ? '' :
        `<label class="t-f"><span class="t-lb">Buscar</span>`
      + `<input type="search" class="t-inp" data-t="buscar" placeholder="Buscar en la tabla…" autocomplete="off"></label>`)
    + `<div class="t-fila">`
    +   `<label class="t-f"><span class="t-lb">Ordenar por</span><select class="t-sel" data-t="orden">${ordenOpts}</select></label>`
    +   `<button type="button" class="t-dir" data-t="dir"><span class="t-dir-ic">${asc ? '↑' : '↓'}</span><span class="t-dir-tx">${dirTx}</span></button>`
    + `</div>`
    + (filtros ? `<div class="t-fila">${filtros}</div>` : '')
    + `<div class="t-pie"><span class="t-cont" data-t="cont">Mostrando ${n} ${n === 1 ? 'fila' : 'filas'}</span>`
    +   `<button type="button" class="t-limpiar" data-t="limpiar" hidden>Limpiar filtros</button></div>`
    + `</div>`;
}

function tablaInspector(bk) {
