/* ===================================================================
   TABLAS CON BARRA DE ORDENAR/FILTRAR (bloque "tabla" con ctrl.on en el panel)
   El panel emite el HTML quieto: .m-tabla.t-int > .t-ctrl + .t-scroll > table,
   con data-tipo en cada <th>, data-v (numero ya normalizado) en las celdas
   numericas y data-fija="1" en la fila de total. Aca vive SOLO el comportamiento,
   colgado de document por delegacion para sobrevivir a cada innerHTML.
   Las tablas viejas (sin .t-int) ni se tocan.
   =================================================================== */
function tNorm(s){ return (s||'').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,' ').trim(); }

function tEstado(t){
  if(t._t) return t._t;
  const tb = t.querySelector('tbody'); if(!tb) return null;
  const filas = [].map.call(tb.rows, function(tr, i){
    return { tr:tr, i:i, fija: tr.dataset.fija==='1',
             s: tNorm(tr.textContent),
             k: [].map.call(tr.cells, function(td){ return tNorm(td.textContent); }),
             v: [].map.call(tr.cells, function(td){ return td.dataset.v==null ? null : parseFloat(td.dataset.v); }) };
  });
  const tipos = [].map.call(t.querySelectorAll('thead th'), function(th){ return th.dataset.tipo || 'texto'; });
  t._t = { tb:tb, filas:filas, tipos:tipos, q:'', fil:{},
           orden: t.dataset.tOrden ? +t.dataset.tOrden : (t.dataset.tOrden==='0' ? 0 : null),
           dir: t.dataset.tDir==='asc' ? 'asc' : 'desc' };
  return t._t;
}

function tPintar(t){
  const st = tEstado(t); if(!st) return;
  const todas = st.filas.filter(function(f){ return !f.fija; });
  let vis = todas;
  if(st.q) vis = vis.filter(function(f){ return f.s.indexOf(st.q) >= 0; });
  Object.keys(st.fil).forEach(function(c){
    const val = st.fil[c]; if(!val) return;
    vis = vis.filter(function(f){ return (f.k[c]||'') === val; });
  });
  if(st.orden !== null && st.tipos[st.orden]){
    const c = st.orden, tipo = st.tipos[c];
    const num = (tipo==='num' || tipo==='plata' || tipo==='fecha'), mul = st.dir==='asc' ? 1 : -1;
    vis = vis.slice().sort(function(a,b){
      const av = num ? a.v[c] : (a.k[c]||''), bv = num ? b.v[c] : (b.k[c]||'');
      const ae = (av===null || av==='' || av!==av), be = (bv===null || bv==='' || bv!==bv);
      if(ae !== be) return ae ? 1 : -1;                 /* las celdas vacias, SIEMPRE ultimas */
      if(ae) return a.i - b.i;
      if(num) return (av - bv)*mul || (a.i - b.i);
      return av.localeCompare(bv,'es',{sensitivity:'base',numeric:true})*mul || (a.i - b.i);
    });
  }
  /* saco y reinserto los <tr> reales: asi el cebreado nth-child(odd/even) se recalcula solo */
  const frag = document.createDocumentFragment();
  vis.forEach(function(f){ frag.appendChild(f.tr); });
  const completo = vis.length === todas.length;
  st.filas.forEach(function(f){ if(f.fija && completo) frag.appendChild(f.tr); else if(f.fija && f.tr.parentNode) f.tr.parentNode.removeChild(f.tr); });
  st.tb.innerHTML = '';
  st.tb.appendChild(frag);

  const cont = t.querySelector('[data-t="cont"]');
  if(cont) cont.textContent = completo
    ? ('Mostrando ' + todas.length + (todas.length===1 ? ' fila' : ' filas'))
    : ('Mostrando ' + vis.length + ' de ' + todas.length + ' filas');
  const activo = !!st.q || Object.keys(st.fil).some(function(c){ return !!st.fil[c]; });
  const lim = t.querySelector('[data-t="limpiar"]'); if(lim) lim.hidden = !activo;

  let vacio = t.querySelector('.t-vacio');
  if(!vis.length){
    if(!vacio){ vacio = document.createElement('div'); vacio.className = 't-vacio'; vacio.textContent = 'No hay filas que coincidan.'; t.appendChild(vacio); }
    vacio.hidden = false;
  } else if(vacio) vacio.hidden = true;

  [].forEach.call(t.querySelectorAll('thead th'), function(th){ th.classList.toggle('t-on', st.orden!==null && +th.dataset.c===st.orden); });
  t.dataset.tDir = st.dir;
  tDirTexto(t, st);
}

/* el boton dice "Mayor a menor" con numeros y "Z → A" con texto: el vendedor no traduce */
function tDirTexto(t, st){
  const b = t.querySelector('[data-t="dir"]'); if(!b) return;
  const asc = st.dir==='asc';
  const texto = st.orden===null || st.tipos[st.orden]==='texto';
  const tx = texto ? (asc ? 'A → Z' : 'Z → A') : (asc ? 'Menor a mayor' : 'Mayor a menor');
  const ic = b.querySelector('.t-dir-ic'), lb = b.querySelector('.t-dir-tx');
  if(ic) ic.textContent = asc ? '↑' : '↓';
  if(lb) lb.textContent = tx;
  b.setAttribute('aria-label', 'Orden actual: ' + tx + '. Tocá para invertir');
}

function tablaInit(root){
  [].forEach.call((root||document).querySelectorAll('.m-tabla.t-int'), function(t){ tPintar(t); });
}

document.addEventListener('input', function(e){
  const inp = e.target.closest && e.target.closest('.m-tabla.t-int [data-t="buscar"]');
  if(!inp) return;
  const t = inp.closest('.m-tabla'), st = tEstado(t); if(!st) return;
  st.q = tNorm(inp.value); tPintar(t);
});
document.addEventListener('change', function(e){
  const el = e.target.closest && e.target.closest('.m-tabla.t-int [data-t="orden"], .m-tabla.t-int [data-t="filtro"]');
  if(!el) return;
  const t = el.closest('.m-tabla'), st = tEstado(t); if(!st) return;
  if(el.dataset.t==='orden') st.orden = el.value==='' ? null : +el.value;
  else st.fil[+el.dataset.c] = tNorm(el.value);
  tPintar(t);
});
document.addEventListener('click', function(e){
  const el = e.target.closest && e.target.closest('.m-tabla.t-int [data-t="dir"], .m-tabla.t-int [data-t="limpiar"], .m-tabla.t-int thead th');
  if(!el) return;
  const t = el.closest('.m-tabla'), st = tEstado(t); if(!st) return;
  if(el.dataset.t==='dir'){ st.dir = st.dir==='asc' ? 'desc' : 'asc'; }
  else if(el.dataset.t==='limpiar'){
    st.q = ''; st.fil = {};
    const i = t.querySelector('[data-t="buscar"]'); if(i) i.value = '';
    [].forEach.call(t.querySelectorAll('[data-t="filtro"]'), function(s){ s.value = ''; });
  }
  else {                                   /* toque en el encabezado: ordena por esa columna */
    const c = +el.dataset.c; if(isNaN(c)) return;
    if(st.orden===c) st.dir = st.dir==='asc' ? 'desc' : 'asc';
    else { st.orden = c; st.dir = st.tipos[c]==='texto' ? 'asc' : 'desc'; }
    const sel = t.querySelector('[data-t="orden"]'); if(sel) sel.value = String(c);
  }
  tPintar(t);
});

document.getElementById('secBody').innerHTML = body;
plegarGalerias(document.getElementById('secBody'), key);
tablaInit(document.getElementById('secBody'));      /* tablas con barra de filtros */

